   133→      final BeaconBlockBody body,
   134→      final IndexedAttestationCache indexedAttestationCache,
   135→      final Supplier<BeaconStateMutators.ValidatorExitContext> validatorExitContextSupplier)
   136→      throws BlockProcessingException {
   137→    super.processOperationsNoValidation(
   138→        state, body, indexedAttestationCache, validatorExitContextSupplier);
   139→
   140→    safelyProcess(
   141→        () ->
   142→            processBlsToExecutionChangesNoValidation(
   143→                MutableBeaconStateCapella.required(state),
   144→                body.getOptionalBlsToExecutionChanges()
   145→                    .orElseThrow(
   146→                        () ->
   147→                            new BlockProcessingException(
   148→                                "BlsToExecutionChanges was not found during block processing."))));
   149→  }
