   151→  @Override
   152→  public void processBlsToExecutionChanges(
   153→      final MutableBeaconState state,
   154→      final SszList<SignedBlsToExecutionChange> blsToExecutionChanges)
   155→      throws BlockProcessingException {
   156→    final BlockValidationResult result =
   157→        verifyBlsToExecutionChangesPreProcessing(
   158→            state, blsToExecutionChanges, BLSSignatureVerifier.SIMPLE, true);
   159→    if (!result.isValid()) {
   160→      throw new BlockProcessingException(result.getFailureReason());
   161→    }
   162→    processBlsToExecutionChangesNoValidation(
   163→        MutableBeaconStateCapella.required(state), blsToExecutionChanges);
   164→  }
