   166→  // process_bls_to_execution_change
   167→  public void processBlsToExecutionChangesNoValidation(
   168→      final MutableBeaconStateCapella state,
   169→      final SszList<SignedBlsToExecutionChange> signedBlsToExecutionChanges) {
   170→
   171→    for (SignedBlsToExecutionChange signedBlsToExecutionChange : signedBlsToExecutionChanges) {
   172→      BlsToExecutionChange addressChange = signedBlsToExecutionChange.getMessage();
   173→      final int validatorIndex = addressChange.getValidatorIndex().intValue();
   174→      Validator validator = state.getValidators().get(validatorIndex);
   175→      state
   176→          .getValidators()
   177→          .set(
   178→              validatorIndex,
   179→              validator.withWithdrawalCredentials(
   180→                  getWithdrawalAddressFromEth1Address(addressChange.getToExecutionAddress())));
   181→    }
   182→  }
