   186→  public void processWithdrawals(
   187→      final MutableBeaconState genericState, final ExecutionPayloadSummary payloadSummary)
   188→      throws BlockProcessingException {
   189→    final ExpectedWithdrawals expectedWithdrawals = getExpectedWithdrawals(genericState);
   190→    expectedWithdrawals.processWithdrawals(
   191→        genericState,
   192→        payloadSummary,
   193→        schemaDefinitionsCapella,
   194→        beaconStateMutators,
   195→        specConfigCapella);
