   204→  @VisibleForTesting
   205→  public static Bytes32 getWithdrawalAddressFromEth1Address(final Bytes20 toExecutionAddress) {
   206→    return Bytes32.wrap(
   207→        Bytes.concatenate(ETH1_WITHDRAWAL_KEY_PREFIX, toExecutionAddress.getWrappedBytes()));
   208→  }
   209→
   210→  @VisibleForTesting
   211→  BlockValidationResult verifyBlsToExecutionChangesPreProcessing(
   212→      final BeaconState genericState,
   213→      final SszList<SignedBlsToExecutionChange> signedBlsToExecutionChanges,
   214→      final BLSSignatureVerifier signatureVerifier,
   215→      final boolean executeValidationRules) {
   216→
   217→    final Set<UInt64> validatorsSeenInBlock = new HashSet<>();
   218→    for (SignedBlsToExecutionChange signedBlsToExecutionChange : signedBlsToExecutionChanges) {
   219→      final BlsToExecutionChange addressChange = signedBlsToExecutionChange.getMessage();
   220→
   221→      if (!validatorsSeenInBlock.add(addressChange.getValidatorIndex())) {
   222→        return BlockValidationResult.failed(
   223→            "Duplicated BlsToExecutionChange for validator " + addressChange.getValidatorIndex());
   224→      }
   225→
   226→      if (executeValidationRules) {
   227→        final Optional<OperationInvalidReason> operationInvalidReason =
   228→            operationValidator.validateBlsToExecutionChange(
   229→                genericState.getFork(), genericState, addressChange);
   230→        if (operationInvalidReason.isPresent()) {
   231→          return BlockValidationResult.failed(operationInvalidReason.get().describe());
   232→        }
   233→      }
   234→
   235→      boolean signatureValid =
   236→          operationSignatureVerifier.verifyBlsToExecutionChangeSignature(
   237→              genericState, signedBlsToExecutionChange, signatureVerifier);
   238→      if (!signatureValid) {
   239→        return BlockValidationResult.failed(
   240→            "BlsToExecutionChange signature is invalid: " + signedBlsToExecutionChange);
   241→      }
   242→    }
   243→    return BlockValidationResult.SUCCESSFUL;
   244→  }
   245→}
