   155→  static WithdrawalSummary getPendingPartialWithdrawals(
   156→      final BeaconStateElectra preState,
   157→      final SchemaDefinitionsElectra schemaDefinitions,
   158→      final MiscHelpersElectra miscHelpers,
   159→      final SpecConfigElectra specConfig) {
   160→    final UInt64 epoch = miscHelpers.computeEpochAtSlot(preState.getSlot());
   161→    final int maxPendingPartialWithdrawals = specConfig.getMaxPendingPartialsPerWithdrawalsSweep();
   162→    final List<Withdrawal> withdrawals = new ArrayList<>();
   163→    int processedPartialWithdrawalsCount = 0;
   164→    UInt64 withdrawalIndex = preState.getNextWithdrawalIndex();
   165→
   166→    for (PendingPartialWithdrawal withdrawal : preState.getPendingPartialWithdrawals()) {
   167→      if (withdrawal.getWithdrawableEpoch().isGreaterThan(epoch)
   168→          || withdrawals.size() == maxPendingPartialWithdrawals) {
   169→        break;
   170→      }
   171→      final int validatorIndex = withdrawal.getValidatorIndex();
   172→      final Validator validator = preState.getValidators().get(validatorIndex);
   173→      final UInt64 partiallyWithdrawnBalance =
   174→          getPartiallyWithdrawnBalance(withdrawals, UInt64.valueOf(validatorIndex));
   175→      final UInt64 remainingBalance =
   176→          preState
   177→              .getBalances()
   178→              .get(withdrawal.getValidatorIndex())
   179→              .get()
   180→              .minusMinZero(partiallyWithdrawnBalance);
   181→      final boolean hasSufficientEffectiveBalance =
   182→          validator
   183→              .getEffectiveBalance()
   184→              .isGreaterThanOrEqualTo(specConfig.getMinActivationBalance());
   185→      final boolean hasExcessBalance =
   186→          remainingBalance.isGreaterThan(specConfig.getMinActivationBalance());
   187→      LOG.trace(
   188→          "pending withdrawal validator index {}, remaining balance {}, requested amount {}; exitEpoch {}, hasSufficientEffectiveBalance {}, hasExcessBalance {}",
   189→          withdrawal.getValidatorIndex(),
   190→          remainingBalance,
   191→          withdrawal.getAmount(),
   192→          validator.getExitEpoch(),
   193→          hasSufficientEffectiveBalance,
   194→          hasExcessBalance);
   195→
   196→      if (validator.getExitEpoch().equals(FAR_FUTURE_EPOCH)
   197→          && hasSufficientEffectiveBalance
   198→          && hasExcessBalance) {
   199→        final UInt64 withdrawableBalance =
   200→            withdrawal
   201→                .getAmount()
   202→                .min(remainingBalance.minusMinZero(specConfig.getMinActivationBalance()));
   203→        withdrawals.add(
   204→            schemaDefinitions
   205→                .getWithdrawalSchema()
   206→                .create(
   207→                    withdrawalIndex,
   208→                    UInt64.valueOf(withdrawal.getValidatorIndex()),
   209→                    getEthAddressFromWithdrawalCredentials(validator),
   210→                    withdrawableBalance));
   211→        withdrawalIndex = withdrawalIndex.increment();
   212→      }
   213→      processedPartialWithdrawalsCount++;
   214→    }
   215→    return new WithdrawalSummary(withdrawals, processedPartialWithdrawalsCount);
   216→  }
