   222→  // get_expected_withdrawals
   223→  private static List<Withdrawal> getExpectedWithdrawals(
   224→      final BeaconStateCapella preState,
   225→      final SchemaDefinitionsCapella schemaDefinitionsCapella,
   226→      final MiscHelpers miscHelpers,
   227→      final SpecConfigCapella specConfigCapella,
   228→      final Predicates predicates,
   229→      final List<Withdrawal> partialWithdrawals) {
   230→    final WithdrawalSchema withdrawalSchema = schemaDefinitionsCapella.getWithdrawalSchema();
   231→    final UInt64 epoch = miscHelpers.computeEpochAtSlot(preState.getSlot());
   232→    final SszList<Validator> validators = preState.getValidators();
   233→    final SszUInt64List balances = preState.getBalances();
   234→    final int validatorCount = validators.size();
   235→    final int maxWithdrawalsPerPayload = specConfigCapella.getMaxWithdrawalsPerPayload();
   236→    final int maxValidatorsPerWithdrawalsSweep =
   237→        specConfigCapella.getMaxValidatorsPerWithdrawalSweep();
   238→    final int bound = Math.min(validatorCount, maxValidatorsPerWithdrawalsSweep);
   239→
   240→    UInt64 withdrawalIndex =
   241→        partialWithdrawals.isEmpty()
   242→            ? preState.getNextWithdrawalIndex()
   243→            : nextWithdrawalAfter(partialWithdrawals);
   244→    int validatorIndex = preState.getNextWithdrawalValidatorIndex().intValue();
   245→
   246→    for (int i = 0; i < bound; i++) {
   247→      final Validator validator = validators.get(validatorIndex);
   248→      if (predicates.hasExecutionWithdrawalCredential(validator)) {
   249→        final UInt64 partiallyWithdrawnBalance =
   250→            getPartiallyWithdrawnBalance(partialWithdrawals, UInt64.valueOf(validatorIndex));
   251→        final UInt64 balance =
   252→            balances.get(validatorIndex).get().minusMinZero(partiallyWithdrawnBalance);
   253→
   254→        if (predicates.isFullyWithdrawableValidatorCredentialsChecked(validator, balance, epoch)) {
   255→          partialWithdrawals.add(
   256→              withdrawalSchema.create(
   257→                  withdrawalIndex,
   258→                  UInt64.valueOf(validatorIndex),
   259→                  getEthAddressFromWithdrawalCredentials(validator),
   260→                  balance));
   261→          withdrawalIndex = withdrawalIndex.increment();
   262→        } else if (predicates.isPartiallyWithdrawableValidatorEth1CredentialsChecked(
   263→            validator, balance)) {
   264→          partialWithdrawals.add(
   265→              withdrawalSchema.create(
   266→                  withdrawalIndex,
   267→                  UInt64.valueOf(validatorIndex),
   268→                  getEthAddressFromWithdrawalCredentials(validator),
   269→                  balance.minusMinZero(miscHelpers.getMaxEffectiveBalance(validator))));
   270→          withdrawalIndex = withdrawalIndex.increment();
   271→        }
   272→
   273→        if (partialWithdrawals.size() == maxWithdrawalsPerPayload) {
   274→          break;
   275→        }
   276→      }
   277→
   278→      validatorIndex = (validatorIndex + 1) % validatorCount;
   279→    }
   280→
   281→    return partialWithdrawals;
   282→  }
   283→
   284→  static UInt64 getPartiallyWithdrawnBalance(
   285→      final List<Withdrawal> currentWithdrawals, final UInt64 validatorIndex) {
   286→    return currentWithdrawals.stream()
   287→        .filter(partialWithdrawal -> partialWithdrawal.getValidatorIndex().equals(validatorIndex))
   288→        .map(Withdrawal::getAmount)
   289→        .reduce(UInt64.ZERO, UInt64::plus);
   290→  }
