   292→  public void processWithdrawals(
   293→      final MutableBeaconState genericState,
   294→      final ExecutionPayloadSummary payloadSummary,
   295→      final SchemaDefinitionsCapella schemaDefinitionsCapella,
   296→      final BeaconStateMutators beaconStateMutators,
   297→      final SpecConfigCapella specConfigCapella)
   298→      throws BlockProcessingException {
   299→    final SszList<Withdrawal> expectedWithdrawals =
   300→        getExpectedWithdrawalsSszList(schemaDefinitionsCapella);
   301→
   302→    assertWithdrawalsInExecutionPayloadMatchExpected(payloadSummary, expectedWithdrawals);
   303→
   304→    processWithdrawalsUnchecked(
   305→        genericState, schemaDefinitionsCapella, beaconStateMutators, specConfigCapella);
   306→  }
   307→
   308→  void processWithdrawalsUnchecked(
   309→      final MutableBeaconState genericState,
   310→      final SchemaDefinitionsCapella schemaDefinitionsCapella,
   311→      final BeaconStateMutators beaconStateMutators,
   312→      final SpecConfigCapella specConfigCapella) {
   313→    final MutableBeaconStateCapella state = MutableBeaconStateCapella.required(genericState);
   314→    final SszList<Withdrawal> expectedWithdrawals =
   315→        getExpectedWithdrawalsSszList(schemaDefinitionsCapella);
   316→
   317→    for (int i = 0; i < expectedWithdrawals.size(); i++) {
   318→      final Withdrawal withdrawal = expectedWithdrawals.get(i);
   319→      beaconStateMutators.decreaseBalance(
   320→          state, withdrawal.getValidatorIndex().intValue(), withdrawal.getAmount());
   321→    }
   322→
   323→    if (partialWithdrawalCount > 0) {
   324→      reducePendingWithdrawals(MutableBeaconStateElectra.required(state));
   325→    }
   326→
   327→    final int validatorCount = genericState.getValidators().size();
   328→    final int maxWithdrawalsPerPayload = specConfigCapella.getMaxWithdrawalsPerPayload();
   329→    final int maxValidatorsPerWithdrawalsSweep =
   330→        specConfigCapella.getMaxValidatorsPerWithdrawalSweep();
   331→    if (!expectedWithdrawals.isEmpty()) {
   332→      final Withdrawal latestWithdrawal = expectedWithdrawals.get(expectedWithdrawals.size() - 1);
   333→      state.setNextWithdrawalIndex(latestWithdrawal.getIndex().increment());
   334→    }
   335→
   336→    if (expectedWithdrawals.size() == maxWithdrawalsPerPayload) {
   337→      // Update the next validator index to start the next withdrawal sweep
   338→      final Withdrawal latestWithdrawal = expectedWithdrawals.get(expectedWithdrawals.size() - 1);
   339→      final int nextWithdrawalValidatorIndex = latestWithdrawal.getValidatorIndex().intValue() + 1;
   340→      state.setNextWithdrawalValidatorIndex(
   341→          UInt64.valueOf(nextWithdrawalValidatorIndex % validatorCount));
   342→    } else {
   343→      // Advance sweep by the max length of the sweep if there was not a full set of withdrawals
   344→      final int nextWithdrawalValidatorIndex =
   345→          state.getNextWithdrawalValidatorIndex().intValue() + maxValidatorsPerWithdrawalsSweep;
   346→      state.setNextWithdrawalValidatorIndex(
   347→          UInt64.valueOf(nextWithdrawalValidatorIndex % validatorCount));
   348→    }
   349→  }
