   351→  private SszList<Withdrawal> getExpectedWithdrawalsSszList(
   352→      final SchemaDefinitionsCapella schemaDefinitions) {
   353→    if (maybeWithdrawalsSszList.isEmpty()) {
   354→      maybeWithdrawalsSszList =
   355→          Optional.of(
   356→              schemaDefinitions
   357→                  .getExecutionPayloadSchema()
   358→                  .getWithdrawalsSchemaRequired()
   359→                  .createFromElements(withdrawalList));
   360→    }
   361→    return maybeWithdrawalsSszList.get();
   362→  }
   363→
   364→  private void reducePendingWithdrawals(final MutableBeaconStateElectra state) {
   365→    final SszListSchema<PendingPartialWithdrawal, ?> schema =
   366→        state.getPendingPartialWithdrawals().getSchema();
   367→    if (state.getPendingPartialWithdrawals().size() == partialWithdrawalCount) {
   368→      state.setPendingPartialWithdrawals(schema.createFromElements(List.of()));
   369→    } else {
   370→      final List<PendingPartialWithdrawal> pendingPartialWithdrawals =
   371→          state.getPendingPartialWithdrawals().asList();
   372→      state.setPendingPartialWithdrawals(
   373→          schema.createFromElements(
   374→              pendingPartialWithdrawals.subList(
   375→                  partialWithdrawalCount, pendingPartialWithdrawals.size())));
   376→    }
   377→  }
   378→
   379→  private static void assertWithdrawalsInExecutionPayloadMatchExpected(
   380→      final ExecutionPayloadSummary payloadSummary, final SszList<Withdrawal> expectedWithdrawals)
   381→      throws BlockProcessingException {
   382→    // the spec does an element-to-element comparison but Teku is comparing the hash of the tree
   383→    if (payloadSummary.getOptionalWithdrawalsRoot().isEmpty()
   384→        || !expectedWithdrawals
   385→            .hashTreeRoot()
   386→            .equals(payloadSummary.getOptionalWithdrawalsRoot().get())) {
   387→      final String msg =
   388→          String.format(
   389→              "Withdrawals in execution payload are different from expected (expected withdrawals root is %s but was "
   390→                  + "%s)",
   391→              expectedWithdrawals.hashTreeRoot(),
   392→              payloadSummary
   393→                  .getOptionalWithdrawalsRoot()
   394→                  .map(Bytes::toHexString)
   395→                  .orElse("MISSING"));
   396→      throw new BlockProcessingException(msg);
   397→    }
